-- GenDB engine variant Q10-wrapped_tables: template q10.sql, kind wrapped_tables (generated by generate.py; frozen)
SELECT
  c_custkey,
  c_name,
  SUM(l_extendedprice * (
    1 - l_discount
  )) AS revenue,
  c_acctbal,
  n_name,
  c_address,
  c_phone,
  c_comment
FROM (
  SELECT
    *
  FROM customer
) AS customer, (
  SELECT
    *
  FROM orders
) AS orders, (
  SELECT
    *
  FROM lineitem
) AS lineitem, (
  SELECT
    *
  FROM nation
) AS nation
WHERE
  c_custkey = o_custkey
  AND l_orderkey = o_orderkey
  AND o_orderdate >= $1
  AND o_orderdate < $1 + INTERVAL '3 MONTH'
  AND l_returnflag = 'R'
  AND c_nationkey = n_nationkey
GROUP BY
  c_custkey,
  c_name,
  c_acctbal,
  c_phone,
  n_name,
  c_address,
  c_comment
ORDER BY
  revenue DESC
LIMIT 20
